package com.fitmind.controller; import com.fitmind.common.Result; import com.fitmind.entity.DailyHealthLetter; import com.fitmind.exception.BusinessException; import com.fitmind.service.HealthLetterService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/health-letters") @RequiredArgsConstructor public class HealthLetterController { private final HealthLetterService service; @GetMapping("/today") public Result<DailyHealthLetter> today(){DailyHealthLetter x=service.findToday();if(x==null)throw BusinessException.notFound("今日健康信尚未生成");return Result.ok(x);} @PostMapping("/generate") public Result<DailyHealthLetter> generate(){return Result.ok(service.generateToday());} }
